// Tariro_ide_idpte/src/omega_os/self_evolution_models.rs

//! Defines data models for Tariro's Self-Evolution & Continuous Improvement module,
//! including self-improvement proposals, evolution plans, and performance evaluation metrics.

use serde::{Serialize, Deserialize};
use chrono::{Utc, DateTime};
use std::collections::HashMap;

use crate::cognitive_arch::learning_models::VerificationStatus; // For verification statuses

/// A proposal generated by Tariro for its own self-improvement or capability enhancement.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SelfImprovementProposal {
    pub id: String,
    pub title: String,
    pub description: String,
    pub proposed_changes: Vec<String>, // e.g., "modify_learning_algorithm", "add_new_cognitive_module"
    pub expected_impact: String,
    pub ethical_review_status: VerificationStatus, // New: Ethical review of the proposed improvement
    pub security_verified: VerificationStatus, // New: Security verification of potential vulnerabilities
    pub proposed_at: DateTime<Utc>,
}

/// A detailed plan for implementing a self-improvement proposal and guiding Tariro's evolution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EvolutionPlan {
    pub id: String,
    pub proposal_id: String, // Link to SelfImprovementProposal
    pub plan_steps: Vec<String>,
    pub estimated_completion_time_hours: u64,
    pub risk_assessment_summary: String,
    pub ethical_compliance: VerificationStatus, // New: Ethical compliance of the evolution plan
    pub security_audited: VerificationStatus, // New: Security audit of the plan implementation
    pub created_at: DateTime<Utc>,
}

/// Metrics used to evaluate the effectiveness and impact of self-evolution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PerformanceEvaluationMetric {
    pub id: String,
    pub evolution_plan_id: String,
    pub metric_name: String, // e.g., "cognitive_efficiency_gain", "error_rate_reduction"
    pub value: f64,
    pub ethical_impact_assessment: VerificationStatus, // New: Ethical impact of performance changes
    pub security_posture_change: VerificationStatus, // New: Security posture changes due to evolution
    pub evaluated_at: DateTime<Utc>,
}

/// A report summarizing the audit of self-evolution and continuous improvement processes.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SelfEvolutionAuditReport {
    pub id: String,
    pub scope: String, // e.g., "all_self_evolution_events", "critical_capability_upgrades"
    pub period_start: DateTime<Utc>,
    pub period_end: DateTime<Utc>,
    pub total_proposals_generated: u64,
    pub plans_executed: u64,
    pub ethical_compliance_status: VerificationStatus, // Overall ethical compliance of self-evolution
    pub security_integrity_status: VerificationStatus, // Overall security integrity of self-evolution systems
    pub blockchain_record_hash: String, // New: Tamper-proof hash from QR-CTFO
    pub generated_at: DateTime<Utc>,
}
